#include <stdio.h>

typedef struct { char name[32]; int age; double salary; } Person;

void to_json(Person *p, char *buf) {
    sprintf(buf, "{\"name\":\"%s\",\"age\":%d,\"salary\":%.2f}", p->name, p->age, p->salary);
}

int main() {
    Person p = {"Alice", 30, 75000.50};
    char json[128];
    to_json(&p, json);
    printf("%s\n", json);
    return 0;
}
